const figures={
 zones:['progressive-zones','Зоны прогрессивной линзы: даль, монитор и чтение.','Условная схема зон: их форма и размеры зависят от конструкции. Цветные полосы нанесены для объяснения — на готовой линзе их нет.'],
 tasks:['progressive-zones','Три дистанции зрения в прогрессивной линзе.','Даль, средняя дистанция и близь требуют разных оптических задач. Прогрессивная конструкция объединяет их в одной линзе.'],
 indices:['thickness','Условное сравнение профиля минусовых линз из материалов с разным индексом.','Схема для одного рецепта и сопоставимого размера: более высокий индекс может уменьшить толщину. Это не расчёт конкретных линз.'],
 coatings:['lens-coatings','Схематичные слои материала и покрытий линзы.','Разные слои решают разные задачи. Схема условная: состав и порядок покрытий зависят от изделия.'],
 screen:['computer-distance','Человек за монитором и расстояние от глаз до экрана.','При выборе очков важно знать расстояние до монитора. Оно может отличаться от расстояния до книги или телефона.'],
 sun:['photochromic','Светлые линзы в помещении и затемнённые линзы на улице.','Фотохром меняет затемнение при изменении условий освещения. Оттенок и скорость реакции зависят от конкретной модели.'],
 driving:['polarization','Отражения от поверхности и условный вид через поляризационную линзу.','Поляризация уменьшает некоторые отражённые блики. Изображение иллюстрирует принцип и не обещает устранение всех бликов.']
};
function figure(key){const [file,alt,caption]=figures[key];return `<figure class="guide-illustration"><img src="/assets/lens-illustrations/${file}.svg" alt="${alt}" width="900" height="460" loading="lazy" decoding="async"><figcaption>${caption}</figcaption></figure>`;}
export function illustratedSection(id,html){
 if(id==='zones')return html.replace(/<div class="guide-zones"[\s\S]*?<\/div>/,figure('zones'));
 if(!figures[id])return html;
 return figure(id)+html+(id==='sun'?figure('driving'):'');
}
